   static long pow(long a, long N) {
       if (N == 0) return 1;
       if (N == 1) return a;
       long R = pow(a, N / 2);
       return (N % 2 == 0) ? R * R : R * R * a;
   }

   static long powMod(long a, long N) {
       if (N == 0) return 1;
       if (N == 1) return a % mod;
       long R = powMod(a, N / 2) % mod;
       R = (R * R) % mod;
       if (N % 2 == 1) {
           R = (R * a) % mod;
       }
       return R % mod;
   }

static void mergeSort(int[] A){
      int n = A.length;
      if (n < 2) return;
      int[] l = new int[n / 2];
      int[] r = new int[n - n / 2];
      System.arraycopy(A, 0, l, 0, n / 2);
      System.arraycopy(A, n / 2, r, 0, n - n / 2);
      mergeSort(l);
      mergeSort(r);
      merge(l, r, A);
