    static void merge(int[] l, int[] r, int[] a){
      int i = 0, j = 0, k = 0;
      while (i < l.length && j < r.length && k < a.length){
        a[k++] = (l[i] < r[j]) ? l[i++] : r[j++];
      }
      while (i < l.length){
        a[k++] = l[i++];
      }
      while (j < r.length){
        a[k++] = r[j++];
      }
    }

